-- Chợ Gần V1: private accounts; public listings; member-only conversations.
create table public.profiles (id uuid primary key references auth.users on delete cascade, name text not null check(length(name) between 1 and 80), area text not null default 'Cầu Giấy', created_at timestamptz default now());
create table public.listings (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id), title text not null check(length(title) between 4 and 160), description text not null check(length(description) between 10 and 4000), price bigint not null check(price>=0), category text not null, area text not null, image_path text not null, status text not null default 'available' check(status in ('available','reserved','sold','hidden')), created_at timestamptz not null default now());
create table public.conversations (id uuid primary key default gen_random_uuid(), listing_id uuid not null references public.listings(id), buyer_id uuid not null references public.profiles(id), seller_id uuid not null references public.profiles(id), created_at timestamptz default now(), unique(listing_id,buyer_id), check(buyer_id<>seller_id));
create table public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id), sender_id uuid not null references public.profiles(id), body text not null check(length(body) between 1 and 2000), created_at timestamptz not null default now());
create table public.favorites (user_id uuid references public.profiles(id) on delete cascade, listing_id uuid references public.listings(id) on delete cascade, primary key(user_id,listing_id));
create table public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id), listing_id uuid not null references public.listings(id), reason text not null check(length(reason) between 5 and 2000), created_at timestamptz default now());
alter table public.profiles enable row level security;
alter table public.listings enable row level security;
alter table public.conversations enable row level security;
alter table public.messages enable row level security;
alter table public.favorites enable row level security;
alter table public.reports enable row level security;
grant select on public.profiles,public.listings to anon,authenticated;
grant insert,update on public.profiles,public.listings to authenticated;
grant select,insert on public.conversations,public.messages,public.reports to authenticated;
grant select,insert,delete on public.favorites to authenticated;
create policy profiles_read on public.profiles for select using(true);
create policy profiles_insert on public.profiles for insert to authenticated with check(id=auth.uid());
create policy profiles_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy listings_read on public.listings for select using(status<>'hidden' or owner_id=auth.uid());
create policy listings_insert on public.listings for insert to authenticated with check(owner_id=auth.uid());
create policy listings_update on public.listings for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy conversations_read on public.conversations for select to authenticated using(auth.uid() in (buyer_id,seller_id));
create policy conversations_insert on public.conversations for insert to authenticated with check(buyer_id=auth.uid() and exists(select 1 from public.listings l where l.id=listing_id and l.owner_id=seller_id and l.status='available'));
create policy messages_read on public.messages for select to authenticated using(exists(select 1 from public.conversations c where c.id=conversation_id and auth.uid() in(c.buyer_id,c.seller_id)));
create policy messages_insert on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversations c where c.id=conversation_id and auth.uid() in(c.buyer_id,c.seller_id)));
create policy favorites_own on public.favorites for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy reports_insert on public.reports for insert to authenticated with check(reporter_id=auth.uid());
create policy reports_read on public.reports for select to authenticated using(reporter_id=auth.uid());
create index listings_feed on public.listings(area,created_at desc);
create index messages_thread on public.messages(conversation_id,created_at);
create function public.on_signup() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,name) values(new.id,left(coalesce(nullif(new.raw_user_meta_data->>'name',''),'Thành viên'),80)); return new; end; $$;
create trigger on_auth_signup after insert on auth.users for each row execute function public.on_signup();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('listing-images','listing-images',true,5242880,array['image/jpeg','image/png','image/webp']);
create policy listing_image_insert on storage.objects for insert to authenticated with check(bucket_id='listing-images' and (storage.foldername(name))[1]=auth.uid()::text);
create policy listing_image_delete on storage.objects for delete to authenticated using(bucket_id='listing-images' and (storage.foldername(name))[1]=auth.uid()::text);
